// C preprocessing sigils. Conditions are emitted verbatim, never evaluated by NanoC.

#include "nanoc/nanoc.h"

// Classifies conditional headers: initial branches 1..3, elif 4, shared else 5.
int nc_pp_kind(NcTokens ts) {
    if ((ts.n && nc_is(ts.v[0], "__nc_pp_else"))) {
        return 5;
    }
    if ((ts.n == 1 && nc_is(ts.v[0], ":"))) {
        return 5;
    }
    if ((ts.n < 2)) {
        return 0;
    }
    if ((nc_is(ts.v[0], ":") && nc_is(ts.v[1], "#"))) {
        return 4;
    }
    if ((!nc_is(ts.v[0], "?"))) {
        return 0;
    }
    return nc_is(ts.v[1], "+") ? 1 : nc_is(ts.v[1], "-") ? 2 : nc_is(ts.v[1], "#") ? 3 : 0;
}

// Emits one conditional directive, excluding the synthetic block colon.
char *nc_pp_header(NcContext *c, NcTokens input, int line) {
    NcTokens ts = nc_significant(c, input);
    if ((ts.n && nc_is(ts.v[ts.n - 1], ":") && ts.n > 1)) {
        --ts.n;
    }
    int kind = nc_pp_kind(ts);
    if ((!kind)) {
        nc_fail(c, line, "invalid preprocessor condition");
    }
    if ((kind == 5)) {
        return "#else\n";
    }
    if ((ts.n < 3)) {
        nc_fail(c, line, "missing preprocessor condition");
    }
    const char *names[] = {"", "ifdef", "ifndef", "if", "elif"};
    if ((kind <= 2 && (ts.n != 3 || ts.v[2].kind != NC_WORD))) {
        nc_fail(c, line, "ifdef/ifndef needs one identifier");
    }
    NcToken start = ts.v[2], end = ts.v[ts.n - 1];
    return nc_format(c, "#%s %.*s\n", names[kind], (int)(end.s + end.n - start.s), start.s);
}

// Emits include, define, undef and error directives, preserving C macro tokens.
char *nc_pp_simple(NcContext *c, NcTokens input, int line) {
    NcTokens ts = nc_significant(c, input);
    if ((!ts.n)) {
        return NULL;
    }
    NcCursor cur = {c, input, 0};
    NcToken first = nc_take(&cur);
    char *name = NULL;
    if ((nc_is(first, "+") && ts.n > 1 && (nc_is(ts.v[1], "<") || ts.v[1].kind == NC_LITERAL))) {
        name = "include";
    } else if ((nc_is(first, "$"))) {
        name = nc_eat(&cur, "-") ? "undef" : nc_eat(&cur, "!") ? "pragma" : "define";
    } else if ((nc_is(first, "!") && ts.n >= 3 && nc_is(ts.v[1], "!") && first.s + first.n == ts.v[1].s && ts.v[2].kind == NC_LITERAL && ts.v[2].s[0] == '"')) {
        (void)nc_take(&cur);
        name = "error";
    }
    if ((!name)) {
        return NULL;
    }
    NcTokens rest = nc_slice(input, cur.pos, input.n);
    if ((!strcmp(name, "define"))) {
        NcTokens parts = nc_significant(c, rest);
        if ((!parts.n || parts.v[0].kind != NC_WORD)) {
            nc_fail(c, line, "define needs a macro name");
        }
        size_t eq = rest.n;
        int nesting = 0;
        for (size_t i = (0), nanoc_bound_1 = (rest.n); i < nanoc_bound_1; ++i) {
            if ((nc_is(rest.v[i], "("))) {
                ++nesting;
            } else if ((nc_is(rest.v[i], ")"))) {
                --nesting;
            } else if ((!nesting && nc_is(rest.v[i], "="))) {
                eq = i;
                break;
            }
        }
        if ((eq == rest.n)) {
            nc_fail(c, line, "use '$ NAME = replacement' for a C macro");
        }
        return nc_format(c, "#define %s %s\n", nc_trim(c, nc_join(c, nc_slice(rest, 0, eq))),
                nc_trim(c, nc_join(c, nc_slice(rest, eq + 1, rest.n))));
    }
    char *text = nc_trim(c, nc_join(c, rest));
    if ((!*text)) {
        nc_fail(c, line, "missing preprocessor operand");
    }
    return nc_format(c, "#%s %s\n", name, text);
}

// Reads and expands a file-scope conditional chain, removing only its indentation level.
char *nc_pp_scope(NcContext *c, NcCursor *cur, NcLayoutLine head, size_t depth) {
    NcBuffer out = {0};
    bool ended = 0;
    for (;;) {
        NcTokens sig = nc_significant(c, head.ts);
        int kind = nc_pp_kind(sig);
        if ((ended)) {
            nc_fail(c, head.line, "branch after preprocessor else");
        }
        ended = kind == 5;
        nc_marker(c, &out, head.line);
        nc_add(c, &out, nc_pp_header(c, head.ts, head.line));
        NcLines body = nc_body_lines(cur, head.line, head.indent);
        NcBuffer source = {0};
        int indent = body.v[0].indent;
        int source_line = body.v[0].line;
        for (size_t i = (0), nanoc_bound_2 = (body.n); i < nanoc_bound_2; ++i) {
            while ((source_line < body.v[i].line)) {
                nc_add(c, &source, "\n");
                ++source_line;
            }
            if ((body.v[i].indent < indent)) {
                nc_fail(c, body.v[i].line, "inconsistent preprocessor indentation");
            }
            char *text = nc_join(c, body.v[i].ts);
            nc_printf(c, &source, "%*s%s\n", body.v[i].indent - indent, "", text);
            ++source_line;
            size_t length = strlen(text);
            for (size_t k = (0), nanoc_bound_3 = (length); k < nanoc_bound_3; ++k) {
                if ((text[k] == '\n')) {
                    ++source_line;
                }
            }
        }
        NcTokens child = nc_lex(c, source.v, body.v[0].line);
        nc_add(c, &out, nc_expand(c, child, depth + 1));
        NcCursor peek = *cur;
        if ((nc_end(&peek))) {
            break;
        }
        NcLayoutLine next = nc_logical_line(&peek);
        int branch = nc_pp_kind(nc_significant(c, next.ts));
        if ((next.indent != head.indent || branch < 4)) {
            break;
        }
        *cur = peek;
        head = next;
    }
    nc_add(c, &out, "\n#endif\n");
    return out.v;
}
